create trigger cards_prevent_board_change
  before update of board_id on public.cards
  for each row
  execute function public.prevent_board_change();

create function public.prevent_board_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if not exists (
    select 1
    from public.board_members m
    join public.boards b on b.id = m.board_id
    where m.board_id = old.board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
      and b.is_archived = false
  ) then
    raise exception 'Not allowed to move this card';
  end if;

  if not exists (
    select 1
    from public.board_members m
    join public.boards b on b.id = m.board_id
    where m.board_id = new.board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
      and b.is_archived = false
  ) then
    raise exception 'Card can only be moved to an editor-accessible board';
  end if;

  return new;
end
$$;

