set search_path = public
as $$
declare
  v_seller uuid;
  v_highest numeric;
  v_increment numeric;
begin
  if auth.role() is distinct from 'authenticated' then
    raise exception 'Not authenticated';
  end if;

  select
    seller_id,
    highest_bid,
    min_increment,
    (highest_bid is null)
  into
    v_seller,
    v_highest,
    v_increment
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'Auction not found';
  end if;

  if current_user = auth.uid() then
    raise exception 'Sellers cannot bid on their own auctions';
  end if;

  if current_timestamp >= ends_at then
    raise exception 'Auction has ended';
  end if;

  if p_amount < (
    case
      when v_highest is null then
        (select starting_price from public.auctions where id = p_auction_id)
      else
        v_highest + v_increment
    end
  ) then
    raise exception 'Bid is too low';
  end if;

  update public.auctions
  set
    highest_bid = p_amount,
    highest_bidder = auth.uid()
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, auth.uid(), p_amount);

  return (select highest_bid from public.auctions where id = p_auction_id);
end
$$;
